export type TrainerPress = {
    code: string;
    label: string;
    shift?: boolean;
};

export type TrainerUnit = {
    text: string;
    sequence: TrainerPress[];
};

export type TrainerStage = {
    id: string;
    type: "learn" | "speed";
    title: string;
    subtitle: string;
    preview: string;
    duration: number;
    requiredWpm: number;
    requiredAccuracy: number;
    nextLine: string;
    units: TrainerUnit[];
};

export type TrainerLesson = {
    id: number;
    slug: string;
    category: string;
    title: string;
    summary: string;
    preview: string;
    focusLabels: string[];
    stages: TrainerStage[];
};

const press = (label: string, code: string, shift = false): TrainerPress => ({
    code,
    label,
    shift,
});

const lesson = (
    id: number,
    slug: string,
    category: string,
    title: string,
    summary: string,
    preview: string,
    focusLabels: string[],
    stages: TrainerStage[],
): TrainerLesson => ({
    id,
    slug,
    category,
    title,
    summary,
    preview,
    focusLabels,
    stages,
});

